MG.xwPiece={n:'ปะติดปะต่อเมื่อคืน',ic:'🧩',mt:'นักสืบในร่างตัวเอง',how:'เทียนข้างหลักฐานแต่ละชิ้นบอกเวลา (เทียนยิ่งเหลือมาก ยิ่งเกิดก่อน) แตะเรียงจากเกิดก่อนไปหลัง 2 รอบ',t:32,rw:()=>'',
 init(B2,api){let rd=0,ok=0,tot=0,stop=0;const show=()=>{if(stop)return;if(rd>=2){api.end();return}const ev=shuf(EVD).slice(0,4);const lv=shuf([0,1,2,3,4]).slice(0,4);const order=lv.map((v,i)=>[v,i]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);let nx=0;
   B2.innerHTML=`<div class="tag2" style="text-align:center">${L('รอบ','Round')} ${rd+1}/2 · ${L('แตะจากเกิดก่อนไปหลัง','Tap from earliest to latest')}</div>${ev.map((e,i)=>`<button class="pbtn" data-i="${i}" style="width:100%;margin:4px 0;text-align:left;padding:9px">${L(e[0],e[1])}<br><small>${CDL[lv[i]]}</small></button>`).join('')}`;
   B2.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(!api.live()||b.disabled)return;const i=+b.dataset.i;tot++;if(i===order[nx]){ok++;b.disabled=true;b.style.opacity=.45;b.insertAdjacentHTML('afterbegin',`<b>${nx+1}.</b> `);nx++;if(nx>=4){rd++;setTimeout(show,450)}}else{b.style.outline='2px solid #ff5a5a';setTimeout(()=>b.style.outline='',300)}})};
  show();return{sc:()=>cl(tot?ok/Math.max(8,tot):0,0,1),stop(){stop=1}}}};
