MG.xwFate={n:'หลบชะตา',ic:'⏳',mt:'ผู้หนีความตาย',how:'ชะตาบอกว่าความตายจะมากับสิ่งไหน เลือกทางที่ไม่มีสิ่งนั้น 5 ครั้ง เวลาจะสั้นลงเรื่อยๆ',t:25,rw:()=>'',
 init(B2,api){let rd=0,ok=0,stop=0,tm=null;const show=()=>{if(stop)return;if(rd>=5){api.end();return}const d=pick(ELM);const others=ELM.filter(x=>x!==d);const safe=Ri(0,2);
   const paths=[0,1,2].map(i=>{const a=shuf(others).slice(0,2);if(i!==safe)a[Ri(0,1)]=d;return a});
   B2.innerHTML=`<div class="item" style="text-align:center">⏳ ${L('ความตายจะมากับ','Death will come with')} <b>${d[0]} ${L(d[1],d[2])}</b></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px">${paths.map((p,i)=>`<button class="pbtn" data-i="${i}" style="font-size:26px;padding:16px 0">${p.map(x=>x[0]).join('')}<br><small>${L('ทาง','Path')} ${i+1}</small></button>`).join('')}</div>`;
   const go=i=>{clearTimeout(tm);if(i===safe)ok++;rd++;setTimeout(show,300)};B2.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(api.live())go(+b.dataset.i)});tm=setTimeout(()=>{if(api.live())go(-1)},Math.max(1300,Math.round((3200-rd*380)*api.ez)))};
  show();return{sc:()=>ok/5,stop(){stop=1;clearTimeout(tm)}}}};
