MG.xwPairs={n:'ถอดความคำทำนาย',ic:'🔮',mt:'ผู้อ่านลิขิต',how:'เปิดการ์ดทีละสองใบ จับคู่สัญลักษณ์ให้ครบ 6 คู่',t:40,rw:()=>'',
 init(B2,api){const SY=shuf(['🗡️','👑','🌑','🕯️','🐍','💔','🌊','🪞']).slice(0,6);const cards=shuf(SY.concat(SY));const op=new Set(),done=new Set();let a=-1,miss=0,lock=0;
  const draw=()=>{B2.innerHTML=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:5px">${cards.map((c,i)=>`<button data-i="${i}" style="height:62px;border-radius:10px;border:1px solid #6a5a9a;background:${done.has(i)?'#2a4a2a':'#221a3a'};font-size:26px">${op.has(i)||done.has(i)?c:'🔮'}</button>`).join('')}</div><div class="tag2" style="text-align:center;margin-top:5px">${L('คู่ที่ถอดได้','Pairs')} ${done.size/2}/6 · ${L('พลาด','Misses')} ${miss}</div>`;
   B2.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(!api.live()||lock)return;const i=+b.dataset.i;if(done.has(i)||op.has(i))return;op.add(i);if(a<0){a=i;draw();return}if(cards[a]===cards[i]){done.add(a);done.add(i);op.clear();a=-1;draw();if(done.size===12)api.end()}else{miss++;lock=1;draw();setTimeout(()=>{op.clear();a=-1;lock=0;draw()},650)}})};
  draw();return{sc:()=>cl(done.size/12-miss*.03,0,1)}}};
