MG.xwProve={n:'จังหวะที่ทุกคนมองข้าม',ic:'🎯',mt:'คนที่ถูกทิ้งแล้วกลับมา',how:'แตะเพื่อหยุดแถบในโซนเขียว โดนแล้วโซนแคบลง 5 ครั้ง',t:20,rw:()=>'',
 init(B2,api){let x=0,dir=1,w=.3,c=.5,hit=0,n=0,stop=0;
  B2.innerHTML=`<div style="position:relative;height:46px;border-radius:12px;background:#221a3a;overflow:hidden;margin-top:10px"><div id="xpZ" style="position:absolute;top:0;bottom:0;background:#2f8a4a"></div><div id="xpN" style="position:absolute;top:0;bottom:0;width:6px;background:#ffd84a"></div></div><div class="tag2" id="xpH" style="text-align:center;margin:6px 0"></div><button class="pbtn" id="xpB" style="width:100%;padding:18px 0;font-size:20px">🎯 ${L('หยุด','Stop')}</button>`;
  const Z=B2.querySelector('#xpZ'),N=B2.querySelector('#xpN'),H=B2.querySelector('#xpH');const zon=()=>{c=.15+rnd()*.7;Z.style.left=((c-w/2)*100)+'%';Z.style.width=(w*100)+'%'};zon();const upd=()=>{H.textContent=`${L('โดน','Hits')} ${hit}/${n} · ${L('เหลือ','left')} ${5-n}`};upd();
  const iv=setInterval(()=>{if(stop)return;x+=dir*(.018+n*.004)/Math.sqrt(api.ez);if(x>1){x=1;dir=-1}if(x<0){x=0;dir=1}N.style.left=(x*100)+'%'},16);
  B2.querySelector('#xpB').onpointerdown=e=>{e.preventDefault();if(!api.live())return;n++;if(Math.abs(x-c)<=w/2){hit++;w=Math.max(.06,w*.72)}zon();upd();if(n>=5)api.end()};
  return{sc:()=>hit/5,stop(){stop=1;clearInterval(iv)}}}};
