  const Gg=B2.querySelector('#xsG'),H=B2.querySelector('#xsH');const upd=()=>{Gg.style.height=g+'%';H.innerHTML=`${L('คนสงสัย','Suspicion')} ${sus}<br>${L('ถูกเห็น','Seen')} ${exp}`};upd();
