function prStart(){const x=X();if(x.pr||x.ev.pr||S.age<6||S.age>12||rnd()>.06)return false;x.ev.pr=1;const p=pick(PR);x.pr={id:p.id,k0:S.karma||0,pk:S.fame||0,lo:1,run:0,face:0,n:0};
 choice('🔮 '+L('คำทำนายตอนเด็ก','A childhood prophecy'),L(`นักพรตเร่ร่อนหยุดหน้าบ้าน มองคุณแล้วพูดประโยคเดียว <b>"${p.t[0]}"</b> แล้วเดินจากไป พ่อแม่ไม่พูดถึงเรื่องนี้อีกเลย แต่คุณจำได้ทุกคำ`,`A wandering priest stops at your door, looks at you, and says one sentence: <b>"${p.t[1]}"</b> Then he walks away. Your parents never mention it again, but you remember every word.`),[
  O('🔮 '+L('จำไว้','Remember it'),L('คำทำนายมีหลายความหมาย ชีวิตของคุณจะเป็นตัวเลือก','A prophecy has many meanings. Your life will choose one'),()=>{})]);return true}
function prYear(){const x=X(),p=x.pr;if(!p)return;p.pk=Math.max(p.pk,S.fame||0);if(S.maxHp)p.lo=Math.min(p.lo,S.hp/S.maxHp)}
function prEv(){const x=X(),p=x.pr;if(!p||p.done||p.n>=2||S.age<20||rnd()>.08)return false;p.n++;const P0=PR.find(z=>z.id===p.id);
 choice('🔮 '+L('คำทำนายกลับมา','The prophecy returns'),L(`ในงานศพคนรู้จัก คุณได้ยินคนแปลกหน้าพูดประโยคเดียวกับที่นักพรตพูดเมื่อหลายปีก่อน <b>"${P0.t[0]}"</b> เขาหันมามองคุณแล้วยิ้ม`,`At an acquaintance's funeral, a stranger speaks the very words the priest said years ago: <b>"${P0.t[1]}"</b> He turns to you and smiles.`),[
  O('🏃 '+L('หนีให้ไกลจากทุกอย่างที่คำทำนายพูดถึง','Run from everything the prophecy names'),L('ยิ่งหนี ยิ่งใกล้ความหมายที่แย่ที่สุด','The more you run, the closer the worst meaning'),()=>{p.run++;say(L('🏃 คุณย้ายบ้าน เปลี่ยนชื่อร้าน เลิกคบคนที่สนิทที่สุด','🏃 You move house, rename your shop, push away those closest to you'),'')}),
  O('🧍 '+L('เผชิญมันตรงๆ','Face it head-on'),'',()=>{p.face++;say(L('🧍 คุณเดินไปถามคนแปลกหน้า เขาหัวเราะ "ข้าเองก็ไม่รู้หรอกว่ามันแปลว่าอะไร"','🧍 You ask the stranger. He laughs. "I don\'t know what it means either."'),'')}),
  O('🔮 '+L('ถอดความ (มินิเกม)','Decode it (minigame)'),L('เห็นทางที่ชีวิตกำลังพาไป','See where your life is heading'),()=>mgo('xwPairs',{},sc=>{if(sc>=.6){const k=prPick(p,P0);say(`🔮 ${L('ภาพที่เห็นในการ์ดใบสุดท้าย','The last card shows')}: <i>${L(P0.m[k][1],P0.m[k][2])}</i>`,'epic',true)}else say(L('🔮 การ์ดว่างเปล่า อนาคตยังไม่ตัดสินใจ','🔮 The cards are blank. The future hasn\'t decided'),'')}))]);return true}
function prPick(p,P0){const ok=Object.keys(P0.m).filter(k=>{try{return P0.m[k][0](p)}catch(e){return false}});if(!ok.length)return'C';const s=k=>P0.m[k][3];return p.run>p.face?ok.sort((a,b)=>s(a)-s(b))[0]:ok.sort((a,b)=>s(b)-s(a))[0]}
function prEnd(){const x=S&&S._xw,p=x&&x.pr;if(!p||p.done)return;p.done=1;const P0=PR.find(z=>z.id===p.id);const k=prPick(p,P0);const m=P0.m[k];
 say(`🔮 <b>${L('คำทำนายเป็นจริง','The prophecy came true')}</b> — "${L(P0.t[0],P0.t[1])}"<br>${L(m[1],m[2])}`,'myth',true);try{const c=LS.get('murim_xwpr',{})||{};c[p.id+k]=1;LS.set('murim_xwpr',c)}catch(e){}}
