const oriFor=w=>['hunter','tower','game'].includes(w)?'party':['murim','xian','soul','loop'].includes(w)?'clan':['zombie','doom','beast'].includes(w)?'exile':'debt';
const orOn=()=>!!LS.get('murim_xwor',0);
window.xwOrTog=function(){LS.set('murim_xwor',orOn()?0:1);orPaint()};
function orPaint(){try{const t=$('traits');if(!t)return;let b=$('xwOrB');if(!b){t.insertAdjacentHTML('afterend','<div id="xwOrB" style="margin:8px 0"></div>');b=$('xwOrB')}b.innerHTML=`<button class="${orOn()?'pbtn':'gbtn'}" style="width:100%" onclick="xwOrTog()">📖 ${orOn()?L('ต้นเรื่องแบบนิยาย: เปิด','Novel-style origin: ON'):L('ต้นเรื่องแบบนิยาย (เริ่มต่ำสุดแล้วไต่กลับ)','Novel-style origin (start at rock bottom, climb back)')}</button><div class="tag2" style="margin-top:3px">${L('ฮันเตอร์/หอคอย/เกม: ถูกไล่ออกจากปาร์ตี้ · ยุทธภพ/เซียน/วิญญาณยุทธ์: ถูกตัดชื่อจากตระกูล · ยุคปัจจุบัน: เกิดมาพร้อมหนี้ · ซอมบี้/วันสิ้นโลก/สัตว์: ถูกค่ายเนรเทศ','Hunter/Tower/Game: kicked from the party · Murim/Xian/Soul: struck from the clan · Modern: born into debt · Zombie/Doom/Beast: exiled')}</div>`}catch(e){}}
try{const _dr=doRoll;doRoll=function(){const r=_dr.apply(this,arguments);try{orPaint()}catch(e){}return r}}catch(e){}
function orAssign(){const x=X();if(x.or||x.ev.or||S.age>1)return;x.ev.or=1;if(!orOn()&&rnd()>.06)return;const w=W();const k=oriFor(w);x.or={k,st:0,cr:nm(),kind:0};
 if(k==='debt'){x.or.debt=Math.round(Math.max(3000,(S.money||0)*8+4000));say(L(`📖 พ่อทิ้งหนี้ไว้ ${fmt(x.or.debt)} ก่อนหายตัวไป เจ้าหนี้ชื่อ${esc(x.or.cr)} ยังหนุ่ม และจะโตไปพร้อมคุณ`,`📖 Your father left a debt of ${fmt(x.or.debt)} before vanishing. The creditor, ${esc(x.or.cr)}, is young and will grow up alongside you`),'epic',true)}
 else say(`📖 ${L('ต้นเรื่องชีวิตนี้','This life\'s opening')}: <b>${L(ORI[k][0],ORI[k][1])}</b>`,'epic',true)}
